    defaultSet?: string
    aliases?: Partial<IIconAliases>
    sets?: Record<string, IIconSet>
}

export type TInfiniteScrollSide = `${INFINITE_SCROLL_SIDE}`

// Where INFINITE_SCROLL_SIDE is:
export enum INFINITE_SCROLL_SIDE {
    START = 'start',
    END   = 'end',
    BOTH  = 'both'
}

export type TLines = `${LINES}`

// Where LINES is:
export enum LINES {
    ONE   = 'one',
    TWO   = 'two',
    THREE = 'three'
}

export type TListItemSlot = {
    isActive: boolean
    isSelected: boolean
    isIndeterminate: boolean
    select: (value: boolean) => void
}

export type TLoadingValue = boolean | number | TLoaderConfig

// Where TLoaderConfig is:
export type TLoaderConfig =
    | ({ type: 'line' }     & Partial<IProgressLinearProps>)
    | ({ type: 'circular' } & Partial<IProgressCircularProps>)
    | ({ type: 'skeleton' } & Partial<ISkeletonProps>)

export type TLocationStrategyFn = (
    data: ILocationStrategyData,
    props: ILocationStrategyProps,
    contentStyles: Ref<Record<string, string>>
) => undefined | { updateLocation: (e: Event) => void }

export type TMode = `${MODE}`

// Where MODE is:
export enum MODE {
    HORIZONTAL = 'horizontal',
    VERTICAL   = 'vertical',
    SHIFT      = 'shift'
}

export type TObserveHandler = (
    isIntersecting: boolean,
    entries: Array<IntersectionObserverEntry>,
    observer: IntersectionObserver
) => void

export type TOpenStrategyFns = {
    open: TOpenStrategyFn
    select: TOpenSelectStrategyFn
}

export type TParsedAnchor =
    | { side: 'center', align: 'center' }
    | { side: TBlock, align: TInline | 'center' }
    | { side: TInline, align: TBlock | 'center' }

export type TPosition = `${POSITION}`

// Where POSITION is:
export enum POSITION {
    STATIC   = 'static',
    RELATIVE = 'relative',
    FIXED    = 'fixed',
    ABSOLUTE = 'absolute',
    STICKY   = 'sticky'
}

export type TQualityOption = {
    /** Stable identifier exposed via `quality-change` (e.g. `"1080p"`). */
    quality: string
    /** Human-readable label shown in the menu. */
    label: string
    /** Optional source URL — only used when the parent wants to embed
     *  it inside the option for a one-shot swap. The Controller never
     *  reads this field; consumers do. */
    src?: string
    /** Optional MIME type — same rationale as `src`. */
    type?: string
}

export type TScrollStrategy = `${SCROLL_STRATEGIES}`

// Where SCROLL_STRATEGIES is:
export enum SCROLL_STRATEGIES {
    NONE        = 'none',
    CLOSE       = 'close',
    BLOCK       = 'block',
    REPOSITION  = 'reposition'
}

export type TSelectStrategyTransformInFn = (
    v: Readonly<Array<unknown> | undefined>,
    children: Map<unknown, Array<unknown>>,
    parents: Map<unknown, unknown>
) => Map<unknown, `${SELECTED}`>

export type TSelectStrategyTransformOutFn = (
    v: Map<unknown, `${SELECTED}`>,
    children: Map<unknown, Array<unknown>>,
    parents: Map<unknown, unknown>
) => Array<unknown>

export type TSheetSnapPoint = {
    id: TSheetSnapId
    height: number | string
}

export type TShikiHighlighter = {
    codeToHtml: (code: string, opts: {
        lang: string
        themes?: { light: string, dark: string }
        defaultColor?: false | string
    }) => string
}

